      <div class="form-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" placeholder="Jordan Lee" autocomplete="name" required>
        <p class="error-message" data-error-for="full-name" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input id="email-address" name="email" type="email" placeholder="jordan@example.com" autocomplete="email" required>
        <p class="error-message" data-error-for="email-address" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input id="phone-number" name="phone" type="tel" placeholder="+1 555 123 4567" autocomplete="tel">
