      const value = input.value;
      const validatorName = input.name === "fullName" ? "fullName" : input.name;
      const message = validators[validatorName](value);

      showError(input, message);
      return !message;
    }

    Object.values(fields).forEach((input) => {
      input.addEventListener("blur", () => validateInput(input));
      input.addEventListener("input", () => {
        if (input.closest(".form-field").classList.contains("invalid")) {
          validateInput(input);
        }
        successMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      successMessage.textContent = "";

      const isValid = Object.values(fields).every((input) => validateInput(input));

      if (!isValid) {
        return;
      }

      successMessage.textContent = "Thanks - your support request is ready to send.";
      form.reset();
      Object.values(fields).forEach((input) => showError(input, ""));
    });
