<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(16, 24, 42, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e5eefb;
      --muted: #97a6ba;
      --accent: #60a5fa;
      --accent-strong: #3b82f6;
      --error: #fda4af;
      --error-strong: #fb7185;
      --input: rgba(15, 23, 42, 0.9);
      --input-border: rgba(148, 163, 184, 0.24);
      --shadow: 0 24px 80px rgba(2, 6, 23, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(59, 130, 246, 0.18), transparent 34%),
        linear-gradient(180deg, #111827 0%, #020617 100%);
      color: var(--text);
    }

    .support-card {
      width: min(100%, 560px);
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(14px);
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(1.9rem, 3vw, 2.4rem);
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-size: 0.95rem;
      font-weight: 700;
      letter-spacing: 0.01em;
    }

    input {
      width: 100%;
      padding: 14px 16px;
      border: 1px solid var(--input-border);
      border-radius: 14px;
      background: var(--input);
      color: var(--text);
      font-size: 1rem;
      outline: none;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(96, 165, 250, 0.18);
    }

    .helper-text {
      color: var(--muted);
      font-size: 0.88rem;
      line-height: 1.5;
    }

    .error-message {
      min-height: 1.15em;
      color: var(--error);
      font-size: 0.88rem;
    }

    .form-field.invalid input {
      border-color: var(--error-strong);
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
    }

    button {
      margin-top: 4px;
      padding: 14px 18px;
      border: 0;
      border-radius: 14px;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #eff6ff;
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      box-shadow: 0 18px 30px rgba(37, 99, 235, 0.28);
    }

    button:hover,
    button:focus-visible {
      transform: translateY(-1px);
      filter: brightness(1.05);
    }

    .success-message {
      margin: 0;
      color: #86efac;
      font-size: 0.95rem;
      min-height: 1.2em;
    }

    @media (max-width: 640px) {
      .support-card {
        padding: 24px;
        border-radius: 20px;
      }
    }
  </style>
</head>
<body>
  <main class="support-card">
    <h1>Contact support</h1>
    <p class="intro">Share your details and a support specialist will reach out to help with your request.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" placeholder="Jordan Lee" autocomplete="name" aria-describedby="full-name-error" required>
        <p class="error-message" id="full-name-error" data-error-for="full-name" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input id="email-address" name="email" type="email" placeholder="jordan@example.com" autocomplete="email" aria-describedby="email-address-error" required>
        <p class="error-message" id="email-address-error" data-error-for="email-address" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input id="phone-number" name="phone" type="tel" placeholder="+1 555 123 4567" autocomplete="tel" aria-describedby="phone-number-help phone-number-error">
        <p class="helper-text" id="phone-number-help">Optional. Enter digits with spaces, dashes, or parentheses, for example: +1 555 123 4567.</p>
        <p class="error-message" id="phone-number-error" data-error-for="phone-number" aria-live="polite"></p>
      </div>

      <button type="submit">Submit</button>
      <p class="success-message" id="success-message" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const successMessage = document.getElementById("success-message");

    const fields = {
      fullName: document.getElementById("full-name"),
      email: document.getElementById("email-address"),
      phone: document.getElementById("phone-number")
    };

    const validators = {
      fullName(value) {
        if (!value.trim()) {
          return "Full name is required.";
        }
        if (value.trim().length < 2) {
          return "Enter your full name.";
        }
        return "";
      },
      email(value) {
        const trimmed = value.trim();
        if (!trimmed) {
          return "Email address is required.";
        }
        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailPattern.test(trimmed)) {
          return "Enter a valid email address.";
        }
        return "";
      },
      phone(value) {
        const trimmed = value.trim();
        if (!trimmed) {
          return "";
        }
        const phonePattern = /^\+?[0-9\s().-]{7,20}$/;
        if (!phonePattern.test(trimmed)) {
          return "Use 7-20 characters with digits and optional spaces, dashes, or parentheses.";
        }
        return "";
      }
    };

    function showError(input, message) {
      const field = input.closest(".form-field");
      const error = field.querySelector(".error-message");

      field.classList.toggle("invalid", Boolean(message));
      input.setAttribute("aria-invalid", String(Boolean(message)));
      error.textContent = message;
    }

    function validateInput(input) {
      const value = input.value;
      const validatorName = input.name === "fullName" ? "fullName" : input.name;
      const message = validators[validatorName](value);

      showError(input, message);
      return !message;
    }

    Object.values(fields).forEach((input) => {
      input.addEventListener("blur", () => validateInput(input));
      input.addEventListener("input", () => {
        if (input.closest(".form-field").classList.contains("invalid")) {
          validateInput(input);
        }
        successMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      successMessage.textContent = "";

      const validationResults = Object.values(fields).map((input) => validateInput(input));
      const isValid = validationResults.every(Boolean);

      if (!isValid) {
        return;
      }

      successMessage.textContent = "Thanks - your support request is ready to send.";
      form.reset();
      Object.values(fields).forEach((input) => showError(input, ""));
    });
  </script>
</body>
</html>
